param([string]$Root,[ValidateSet('Enable','Disable')][string]$Action,[ValidateSet('None','BeforeMutation','AfterMutation','BeforeReleaseAudit')][string]$Fault='None',[int]$FaultIndex=0)
try{. "$PSScriptRoot/Coordinator.ps1";InvokeCoordinatorLab -Root $Root -Action $Action -Fault $Fault -FaultIndex $FaultIndex|Out-Null;exit 0}catch{if($_.Exception.Message -match '^(coord|profile|journal|integrated|inventory)_[a-z_]+$'){Write-Host $_.Exception.Message}else{Write-Host ('coord_provider_failure_'+$_.Exception.GetType().Name.ToLowerInvariant())};exit 1}
